INSERT INTO allah_names VALUES(81,'The Avenger, The Retributor','The Avenger','(32:22)(43:41)(44:16)','الْمُنْتَقِمُ','Al-Muntaqim','আল-মুনতাক্বিম','অপরাধীর শাস্তিদাতা',NULL);
INSERT INTO allah_names VALUES(82,'The Pardoner, The Effacer of Sins','The Forgiver','(4:99)(4:149)(22:60)','العَفُوُّ','Al-''Afuww','আল-আফুউ','মহাক্ষমাশীল ও মার্জনাকারী',NULL);
INSERT INTO allah_names VALUES(83,'The Compassionate, The All-Pitying','The Most Kind','(3:30)(9:117)(57:9)(59:10)','الرَّؤُوفُ','Ar-Ra''oof','আর-রাউফ','পরম কোমল হৃদয় ও দয়ালু',NULL);
INSERT INTO allah_names VALUES(84,'The Owner of Dominion and Sovereignty','The Sovereign of All','(3:26)','مَالِكُ الْمُلْكِ','Malik-ul-Mulk','মালিকুল মুলক','সমগ্র বিশ্বজগতের মালিক',NULL);
INSERT INTO allah_names VALUES(85,'The Lord of Majesty and Generosity','Possessor of Majesty and Bounty','(55:27)(55:78)','ذُوالْجَلاَلِ وَالإكْرَامِ','Dhul-Jalali wal-Ikram','যুল-জালালি ওয়াল-ইকরাম','মহিমাময় ও মহানুভব',NULL);
INSERT INTO allah_names VALUES(86,'The Equitable, The Requiter','The Equitable One','(7:29)(3:18)','الْمُقْسِطُ','Al-Muqsit','আল-মুকসিত','ন্যায়বিচারক',NULL);
INSERT INTO allah_names VALUES(87,'The Gatherer, The Unifier','The Gatherer','(3:9)','الْجَامِعُ','Al-Jami''','আল-জামি','একত্রকারী',NULL);
INSERT INTO allah_names VALUES(88,'The Self-Sufficient, The Wealthy','The Rich One','(3:97)(39:7)(47:38)(57:24)','الْغَنِيُّ','Al-Ghaniyy','আল-গানী','চির ধনী ও অভাবমুক্ত',NULL);
INSERT INTO allah_names VALUES(89,'The Enricher, The Emancipator','The Enricher','(9:28)','الْمُغْنِي','Al-Mughni','আল-মুগনী','অভাবমোচনকারী',NULL);
INSERT INTO allah_names VALUES(90,'The Preventer, The Defender','The Preventer of Harm','(67:21)','اَلْمَانِعُ','Al-Mani''','আল-মানি','প্রতিরোধকারী',NULL);
INSERT INTO allah_names VALUES(91,'The Creator of Harm (by His Will)','The Creator of Harm','(6:17)','الضَّارَّ','Ad-Darr','আদ-দার্র','অনিষ্টকারী (আল্লাহর হুকুমে)',NULL);
INSERT INTO allah_names VALUES(92,'The Creator of Good, The Propitious','The Bestower of Benefits','(30:37)','النَّافِعُ','An-Nafi''','আন-নাফি','কল্যাণকারী',NULL);
INSERT INTO allah_names VALUES(93,'The Light, The Illuminator','The Light','(24:35)','النُّورُ','An-Noor','আন-নূর','পরম জ্যোতি',NULL);
