INSERT INTO allah_names VALUES(96,'The Everlasting, The Infinite','The Everlasting One','(55:27)','اَلْبَاقِي','Al-Baqi','আল-বাক্বী','চিরস্থায়ী ও অবিনশ্বর',NULL);
INSERT INTO allah_names VALUES(97,'The Supreme Inheritor of All','The Inheritor','(15:23)','الْوَارِثُ','Al-Warith','আল-ওয়ারিস','সকল কিছুর চূড়ান্ত উত্তরাধিকারী',NULL);
INSERT INTO allah_names VALUES(98,'The Guide to the Right Path','The Most Righteous Guide','(2:256)','الرَّشِيدُ','Ar-Rasheed','আর-রাশীদ','সঠিক পথের নির্দেশক',NULL);
INSERT INTO allah_names VALUES(99,'The Timeless, The Most Patient','The Patient One','(2:153)(3:200)(103:3)','الصَّبُورُ','As-Saboor','আস-সবূর','মহা ধৈর্যশীল',NULL);
